/* 08 pure synthetic merchant/reviewer view. Controller remains sole authority owner. */
(function(g){'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=x=>Array.isArray(x)?x:[],valid=n=>Number.isSafeInteger(n)&&n>=0;
const money=n=>valid(n)?'¥'+Math.floor(n/100)+'.'+String(n%100).padStart(2,'0'):'金额待核对';
const labels={pending:'待演示审核',approved:'演示审核通过',rejected:'演示审核未通过'};
const known=p=>Object.hasOwn(labels,p.status);
function counts(s){const products=list(s.products),c={all:products.length,pending:0,approved:0,rejected:0,unknown:0,listed:0};for(const p of products){c[known(p)?p.status:'unknown']++;if(p.status==='approved'&&p.listed===true)c.listed++;}return c;}
const notice='<aside class="cag-notice" role="note"><b>合成商品工作台 · 非真实经营权限</b><p>仅本机演示。商家与审核员是可切换的界面角色，不代表不同真实账号或后端授权。真实身份核验、资质审核、图片上传与对外发布均未接入。</p></aside>';
function locked(o){return o.locked===true||o.authorized!==true||!valid(o.renderToken);}
function disabled(on){return on?' disabled aria-disabled="true" data-cag-disabled="true"':'';}
function button(text,action,id,o,primary=false,off=false){return `<button type="button" class="cag-button${primary?' cag-primary':''}" data-action="${esc(action)}" data-id="${esc(id)}" data-view="${esc(o.renderToken)}"${disabled(locked(o)||off)}>${esc(text)}</button>`;}
function picture(p,o){const path=o.productImages?.[String(p.id)],safe=typeof path==='string'&&/^images\/commerce\/products\/sku-[0-9]+-original-v[0-9]+\.png$/.test(path);return `<figure class="cag-picture"><div class="cag-image-frame"><span aria-hidden="true">◇</span>${safe?`<img src="${esc(path)}" alt="${esc(p.name)} · 原创演示图，非实物照" loading="lazy" decoding="async">`:'<small>商品图未接入</small>'}</div><figcaption>${safe?'既有原创演示图 · 非本次上传':'图片选择与上传未开放'}</figcaption></figure>`;}
function stats(s){const c=counts(s);return `<dl class="cag-stats" aria-label="同一商品快照统计">${[['all','全部'],['pending','待审核'],['approved','已通过'],['rejected','未通过'],['listed','演示可见'],...(c.unknown?[['unknown','状态待核对']]:[])].map(([key,label])=>`<div><dt>${label}</dt><dd>${c[key]}</dd></div>`).join('')}</dl>`;}
function input(name,label,value,o,options={}){const numeric=options.numeric===true;return `<label class="cag-field"><span>${esc(label)}</span><input name="${esc(name)}" type="${numeric?'number':'text'}" value="${esc(numeric?(valid(value)?value:''):(value??''))}"${numeric?' min="0" step="1" max="9007199254740991" inputmode="numeric"':` maxlength="${options.max||500}"`} required${disabled(locked(o)||!valid(o.renderEditor))}></label>`;}
function form(s,o){const editing=o.editing!=null&&o.editing!=='';const p=editing?list(s.products).find(p=>p.id===o.editing):{};if(!p)return `<section class="cag-card"><h2>当前编辑商品已不存在</h2><p>没有替换为新商品表单，避免把旧编辑误提交成新增。</p>${button('取消编辑并核对','clear','',o)}</section>`;return `<form id="product-form" class="cag-card cag-editor" data-editor="${esc(o.renderEditor)}"><div class="cag-heading"><h2>${editing?'编辑商品 · 重新送审':'新增合成商品'}</h2><span class="cag-badge">演示商家</span></div><p class="cag-help">以下是未保存填写，不是已保存草稿。提交后商品会下架并进入待演示审核；不自动发布。</p><div class="cag-image-notice">${picture(p,o)}<div><b>图片上传未开放</b><p>仅可展示已存在的原创演示配图，不代表新商品已经选择、绑定或上传了图片。</p></div></div>${input('name','商品名称',p.name,o,{max:80})}<div class="cag-field-pair">${input('category','类别',p.category,o)}${input('spec','规格（仅标签资料）',p.spec,o)}</div><div class="cag-field-pair">${input('priceCents','演示价格（整数分）',p.priceCents,o,{numeric:true})}${input('stock','演示库存（整数件）',p.stock,o,{numeric:true})}</div><p class="cag-help">价格以分为单位，例如 2890 分 = ¥28.90。缺少价格保持空白，不默认为免费；0 分仅代表明确录入的合成金额。</p>${input('manufacturer','生产商（资料未核验可写“待核验”）',p.manufacturer,o)}${input('ingredients','配料表（未核验不得推测）',p.ingredients,o)}${input('qualification','资质 / 标签核验资料',p.qualification,o)}${input('shelfLife','保质期',p.shelfLife,o)}<label class="cag-field"><span>商品描述</span><textarea name="description" maxlength="2000" rows="4"${disabled(locked(o)||!valid(o.renderEditor))}>${esc(p.description||'')}</textarea></label><p class="cag-help">当前模型没有结构化营养标签或独立持久草稿字段；不会推算热量、配料、剂量或功效。请勿填写真实个人资料。</p><div class="cag-form-actions">${editing?button('取消编辑','clear','',o):''}<button type="submit" class="cag-button cag-primary"${disabled(locked(o)||!valid(o.renderEditor))}>保存并提交演示审核</button></div></form>`;}
function productCard(p,o){let actions='';if(o.role==='merchant')actions=button('编辑 / 重新送审','edit',p.id,o);else if(o.role==='reviewer'&&p.status==='pending')actions=button('演示驳回','reject',p.id,o)+button('演示审核通过','approve',p.id,o,true);else if(o.role==='reviewer'&&p.status==='approved')actions=button(p.listed===true?'演示下架':'演示上架',p.listed===true?'unlist':'list',p.id,o,true);const status=known(p)?labels[p.status]:'状态待核对';return `<article class="cag-card cag-product"><div class="cag-product-top">${picture(p,o)}<div><h3>${esc(p.name||'商品名称待核对')}</h3><span class="cag-badge">${status}</span><p>${p.listed===true?(p.status==='approved'?'演示可见':'状态冲突：非通过商品标为上架'):'未上架'}</p><p>${esc(p.category||'类别待核对')} · ${esc(p.spec||'规格待核对')}</p><strong class="cag-price">${money(p.priceCents)}</strong><small>演示库存 ${valid(p.stock)?p.stock:'待核对'} 件</small></div></div><details><summary>检查商品资料</summary><dl class="cag-facts">${[['商品编号',p.id],['生产商',p.manufacturer],['配料表',p.ingredients],['资质 / 标签',p.qualification],['保质期',p.shelfLife],['资料来源',p.source]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'待核验')}</dd></div>`).join('')}</dl><p>${esc(p.description||'说明待补充')}</p><p class="cag-help">文字填写不等于真实标签或资质验证通过。没有图片上传记录；演示配图不代表真实包装、配料与外观。</p></details><div class="cag-actions">${actions}</div>${o.role==='reviewer'&&p.status==='rejected'?'<p class="cag-help">等待商家修改并重新提交，不在此视图直接通过。</p>':''}${!known(p)?'<p class="cag-help">状态无法识别，审核与上架操作未提供；请核对最新记录。</p>':''}</article>`;}
function audit(s){return `<details class="cag-card cag-audit"><summary>操作审计 · 最近 20 项</summary>${list(s.audit).slice(-20).reverse().map(a=>`<p>版本 ${valid(a.revision)?a.revision:'待核对'} · ${esc(a.action)}</p>`).join('')||'<p>暂无演示操作记录。</p>'}<p class="cag-help">此处是模型操作记录，不是独立审计身份凭证。</p></details>`;}
function render(s,o={}){const role=o.role,products=list(s.products);if(!['merchant','reviewer'].includes(role))return `<section class="cag" data-cag-role="unknown"><header class="cag-header"><a href="shop.html">‹ 返回商城</a><h1>商品工作台</h1></header>${notice}<article class="cag-card"><h2>当前演示角色无法核对</h2><p>未提供编辑、提交或审核操作。请通过现有角色选择器重新核对。</p></article></section>`;const groups=role==='reviewer'?[['pending','待演示审核队列'],['approved','已通过 · 上下架管理'],['rejected','未通过 · 等待修改'],['unknown','状态待核对']]:[['all','商品列表']];return `<section class="cag" data-cag-role="${role}"><header class="cag-header"><a href="shop.html">‹ 返回商城</a><h1>${role==='merchant'?'商品管理':'独立审核视图'}</h1><p>${role==='merchant'?'演示商家 · 编辑与送审，不提供审核按钮':'演示审核员 · 审核与上下架，不提供商家编辑表单'}</p></header>${notice}<p class="cag-help">当前快照版本 ${valid(s.revision)?s.revision:'待核对'} · ${locked(o)?'操作已停用，请等待或核对最新数据':'操作仍须现有控制器核对身份、版本与原请求'}</p>${stats(s)}${role==='merchant'?form(s,o):'<aside class="cag-card cag-help">“演示审核通过”不自动上架；需在通过后的商品卡片单独执行演示上架。真实审核须由服务端校验，不以本地角色切换作为授权。</aside>'}${groups.map(([key,title])=>{const rows=products.filter(p=>key==='all'||(key==='unknown'?!known(p):p.status===key));if(!rows.length&&key!=='all'&&key!=='pending')return '';return `<section class="cag-group"><div class="cag-heading"><h2>${title}</h2><span>${rows.length} 件</span></div>${rows.map(p=>productCard(p,o)).join('')||`<article class="cag-card cag-empty"><h3>${key==='pending'?'暂无待审核商品':'还没有演示商品'}</h3><p>${key==='pending'?'队列来自当前模型，不生成假待办。':'可在上方填写虚构商品资料，明确提交后才会保存。'}</p></article>`}</section>`;}).join('')}${audit(s)}</section>`;}
g.NutriCommerceAdminGlassV1=Object.freeze({render,counts,buildId:'commerce-admin-glass-view-v1'});
})(typeof window!=='undefined'?window:globalThis);
